	private enum PatchKind
	{
		Append,
		UnitTemplateSelectionCollider,
		StructureTarmac,
		HostBuildOrder,
		ConstructionPreview
	}

	private sealed class PatchSpec
	{
		public string RelativePath { get; }

		public string Description { get; }

		public PatchKind Kind { get; }

		public string? Appendix { get; }

		public PatchSpec(string relativePath, string description, string appendix)
		{
			RelativePath = relativePath;
			Description = description;
			string text = appendix.TrimStart('\r', '\n');
			if (string.Equals(description, "Guard host unit classes", StringComparison.Ordinal))
			{
				text = ApplyGuardFactoryUpgradePresentationOwnership(text);
			}
			Appendix = "\n\n-- Supreme Commander Overhaul Structures Cache Patcher 1.6.1\n" + text;
			Kind = PatchKind.Append;
		}

		public PatchSpec(string relativePath, string description, PatchKind kind)
		{
			if (kind == PatchKind.Append)
			{
				throw new ArgumentOutOfRangeException("kind", "Append patches require an appendix.");
			}
			RelativePath = relativePath;
			Description = description;
			Kind = kind;
		}
	}

	private sealed class FactoryGameplaySpec
	{
		public string TargetId { get; }

		public string SourceId { get; }

		public string BlueprintSha256 { get; }

		public string ScriptSha256 { get; }

		public string Faction { get; }

		public int Tier { get; }

		public int Health { get; }

		public int BuildTime { get; }

		public int Alloys { get; }

		public int Energy { get; }

		public int AlloyStorage { get; }

		public int Vision { get; }

		public int BuildPower { get; }

		public string? UpgradesTo { get; }

		public bool DonorRootLoopMuted { get; }

		public FactoryGameplaySpec(string targetId, string sourceId, string blueprintSha256, string scriptSha256, string faction, int tier, int health, int buildTime, int alloys, int energy, int alloyStorage, int vision, int buildPower, string? upgradesTo, bool donorRootLoopMuted)
		{
			TargetId = targetId;
			SourceId = sourceId;
			BlueprintSha256 = blueprintSha256;
			ScriptSha256 = scriptSha256;
			Faction = faction;
			Tier = tier;
			Health = health;
			BuildTime = buildTime;
			Alloys = alloys;
			Energy = energy;
			AlloyStorage = alloyStorage;
			Vision = vision;
			BuildPower = buildPower;
			UpgradesTo = upgradesTo;
			DonorRootLoopMuted = donorRootLoopMuted;
		}
	}

	private sealed class CachedResource
	{
		public PatchSpec Spec { get; }

		public string Path { get; }

		public object Stock { get; }

		public object? Replacement { get; set; }

		public bool ReplacementWasAssigned { get; set; }

		public CachedResource(PatchSpec spec, string path, object stock)
		{
			Spec = spec;
			Path = path;
			Stock = stock;
		}
	}

