		new PatchSpec("LJ/lua/host/units/unitsClasses/unitsDefault.lua", "host progress-bound upgrade animation bridge", "\n-- Engine.PlayAnimation normally owns clip time. The coordinator's native\n-- bridge recognizes this negative cross-fade range as an exact, replicated\n-- authored frame instead, so a source structure follows its upgrade target.\nlocal ProgressAnimationSentinelBase = -10000\nlocal ProgressAnimationSentinelMaximumDuration = 1000\nlocal ProgressAnimationEpsilon = 0.000001\n-- Imported clips are authored at a low visible frame rate. Sampling more\n-- often only repeats native animation bridge calls between visible frames.\nlocal ProgressAnimationSampleIntervalSeconds = 0.1\nlocal mathAbs = math.abs\nlocal mathMax = math.max\nlocal mathMin = math.min\n\n-- Current Sanctuary names this base HostUnit; older builds exposed\n-- Unit. Keep one explicit compatibility binding rather than assuming\n-- either global is present.\nlocal SCOProgressAnimationUnit = HostUnit or Unit\nif not SCOProgressAnimationUnit then\n    error(\"SCO progress animation bridge could not resolve the host unit base class.\")\nend\n\nlocal StockUnitOnStartUpgrading = SCOProgressAnimationUnit.OnStartUpgrading\nlocal StockUnitOnEndUpgrading = SCOProgressAnimationUnit.OnEndUpgrading\nlocal StockUnitPromoteToUnit = SCOProgressAnimationUnit.PromoteToUnit\nlocal StockUnitUpdateAnimations = SCOProgressAnimationUnit.UpdateAnimations\n\n-- Imported factory children occupy custom hull geometry while they build.\n-- Stock promotion enables their collider once; make that one transition\n-- respect the owning factory instead of polling the native bridge each tick.\nif not _G.SupremeCommanderOverhaulFactoryColliderPromotionHookInstalled then\n    _G.SupremeCommanderOverhaulFactoryColliderPromotionHookInstalled = true\n    function SCOProgressAnimationUnit:PromoteToUnit()\n        StockUnitPromoteToUnit(self)\n        if self.scoFactoryColliderPinOwner ~= nil then\n            Engine.SetVolumeColliderEnabled(self.id, false)\n        end\n    end\nend\n\n-- Stock base UpdateAnimations queries Movement before checking whether a\n-- run transition even exists. Rest-only imported rigs have no such path,\n-- so skip that native query without changing any observable animation.\nfunction SCOProgressAnimationUnit:UpdateAnimations()\n    if not self.isAnimated then\n        return\n    end\n    local animations = self.tp.visuals and self.tp.visuals.animations\n    if not animations or not animations.run then\n        return\n    end\n    StockUnitUpdateAnimations(self)\nend\n\nfunction SCOProgressAnimationUnit:ProgressBoundUpgradeAnimationThread(targetUnit, animationId, durationSeconds)\n    local lastFraction = nil\n    while not self.dead\n        and not self.deleted\n        and not targetUnit.dead\n        and not targetUnit.deleted\n        and self:IsUpgrading()\n        and self.upgradeTarget == targetUnit\n    do\n        local fraction = mathMin(mathMax(targetUnit:GetFractionComplete(), 0), 1)\n        if lastFraction == nil or mathAbs(fraction - lastFraction) > ProgressAnimationEpsilon then\n            Engine.PlayAnimation(\n                self.id,\n                animationId,\n                ProgressAnimationSentinelBase + (fraction * durationSeconds)\n            )\n            lastFraction = fraction\n        end\n        WaitSeconds(ProgressAnimationSampleIntervalSeconds)\n    end\n\n    if self.scoProgressBoundUpgradeTarget == targetUnit then\n        self.scoProgressBoundUpgradeThread = nil\n    end\nend\n\nfunction SCOProgressAnimationUnit:StartProgressBoundUpgradeAnimation(targetUnit)\n    local additions = self.tp.additions\n    local binding = additions and additions.progressBoundUpgradeAnimation\n    local animations = self.tp.visuals and self.tp.visuals.animations\n    local animation = binding and animations and animations[binding.animationKey]\n    local durationSeconds = binding and binding.durationSeconds\n    if not animation\n        or not animation.id\n        or type(durationSeconds) ~= \"number\"\n        or durationSeconds <= 0\n        or durationSeconds >= ProgressAnimationSentinelMaximumDuration\n    then\n        return\n    end\n\n    if self.scoProgressBoundUpgradeThread then\n        KillThread(self.scoProgressBoundUpgradeThread)\n    end\n    self.scoProgressBoundUpgradeTarget = targetUnit\n    self.scoProgressBoundUpgradeRestAnimationKey = binding.restAnimationKey or \"walk\"\n    self.scoProgressBoundUpgradeThread = self:NewThread(\n        self.ProgressBoundUpgradeAnimationThread,\n        targetUnit,\n        animation.id,\n        durationSeconds\n    )\nend\n\nfunction SCOProgressAnimationUnit:OnStartUpgrading(targetUnit)\n    StockUnitOnStartUpgrading(self, targetUnit)\n    self:StartProgressBoundUpgradeAnimation(targetUnit)\nend\n\nfunction SCOProgressAnimationUnit:OnEndUpgrading(targetUnit)\n    local activeTarget = self.scoProgressBoundUpgradeTarget\n    local activeThread = self.scoProgressBoundUpgradeThread\n    local restAnimationKey = self.scoProgressBoundUpgradeRestAnimationKey\n\n    StockUnitOnEndUpgrading(self, targetUnit)\n\n    if activeTarget ~= targetUnit then\n        return\n    end\n\n    if activeThread then\n        KillThread(activeThread)\n    end\n    self.scoProgressBoundUpgradeTarget = nil\n    self.scoProgressBoundUpgradeThread = nil\n    self.scoProgressBoundUpgradeRestAnimationKey = nil\n\n    if self.dead or self.deleted then\n        return\n    end\n\n    local animations = self.tp.visuals and self.tp.visuals.animations\n    local restAnimation = animations and animations[restAnimationKey]\n    if restAnimation and restAnimation.id then\n        Engine.PlayAnimation(self.id, restAnimation.id, 0.1)\n    end\nend"),
		new PatchSpec("LJ/lua/host/units/unitsClasses/unitsDefaultGuard.lua", "Guard host unit classes", "\nlocal OrderTasks = Import(\"common/commonOrders.lua\").OrderTasks\nlocal HostOrderManager = Import(\"host/managers/orders/hostOrderManager.lua\")\n\n-- Cybran land factories retain their own native animated rigs. This class\n-- switches their clip for both normal production and self-upgrades.\nlocal GuardLandFactory = HostGuardLandFactory or GuardLandFactory\nif not GuardLandFactory then\n    error(\"SCO could not resolve the host Guard land-factory base class.\")\nend\nHostGuardCybranLandFactory = Class(\"GuardCybranLandFactory\", GuardLandFactory)\nlocal GuardCybranLandFactory = HostGuardCybranLandFactory\n\nfunction GuardCybranLandFactory:UpdateAnimations()\n    -- Static factories have no Movement component. Their authored build\n    -- clips are driven explicitly by the lifecycle methods below.\nend\n\n-- Sanctuary currently uses GetRollOffPoint for the initial build spawn.\n-- Keep the real roll-off table unchanged so completed units still exit.\nfunction GuardCybranLandFactory:GetRollOffPoint()\n    local offset = self.tp.additions and self.tp.additions.buildStagingOffset\n    if not offset then\n        return GuardLandFactory.GetRollOffPoint(self)\n    end\n\n    local point = self:GetPosition()\n    point.x = point.x + offset.x\n    point.y = point.y + offset.y\n    point.z = point.z + offset.z\n    return point\nend\n\nlocal function GetCybranFactoryRollOffRamps(factory)\n    local additions = factory.tp.additions\n    return additions and additions.rollOffRamps\nend\n\nlocal function GetCybranFactoryRollOffRampPosition(factory, offset)\n    local factoryPosition = factory:GetPosition()\n    return EngineClasses.float3(\n        factoryPosition.x + (offset.x or 0),\n        factoryPosition.y + (offset.y or 0),\n        factoryPosition.z + (offset.z or 0)\n    )\nend\n\nlocal function GetCybranFactoryRollOffTargetKey(targetUnit)\n    local id = targetUnit and targetUnit.id\n    if not id then\n        return nil\n    end\n    return tostring(id.index) .. \":\" .. tostring(id.version)\nend\n\nlocal function SelectCybranFactoryRollOffRamp(factory, targetUnit)\n    local ramps = GetCybranFactoryRollOffRamps(factory)\n    if not ramps or #ramps == 0 then\n        return nil\n    end\n\n    local key = GetCybranFactoryRollOffTargetKey(targetUnit)\n    local selectedIndexes = factory.guardCybranRollOffRampIndexes\n    local selectedIndex = key and selectedIndexes and selectedIndexes[key]\n    if selectedIndex then\n        return ramps[selectedIndex]\n    end\n\n    local source = factory.unitBeingBuiltSource or factory\n    local rallyPoint = source.rallyPoint\n    if rallyPoint then\n        local closestDistanceSquared = nil\n        for index, ramp in ipairs(ramps) do\n            local clearancePosition = GetCybranFactoryRollOffRampPosition(factory, ramp.clearanceOffset or ramp.rampOffset)\n            local deltaX = clearancePosition.x - rallyPoint.x\n            local deltaZ = clearancePosition.z - rallyPoint.z\n            local distanceSquared = (deltaX * deltaX) + (deltaZ * deltaZ)\n            if not closestDistanceSquared or distanceSquared < closestDistanceSquared then\n                closestDistanceSquared = distanceSquared\n                selectedIndex = index\n            end\n        end\n    else\n        selectedIndex = factory.guardCybranNextRollOffRampIndex or 1\n        if selectedIndex < 1 or selectedIndex > #ramps then\n            selectedIndex = 1\n        end\n        factory.guardCybranNextRollOffRampIndex = selectedIndex + 1\n        if factory.guardCybranNextRollOffRampIndex > #ramps then\n            factory.guardCybranNextRollOffRampIndex = 1\n        end\n    end\n\n    if key then\n        factory.guardCybranRollOffRampIndexes = selectedIndexes or {}\n        factory.guardCybranRollOffRampIndexes[key] = selectedIndex\n    end\n    return ramps[selectedIndex]\nend\n\nlocal function FaceCybranFactoryUnitTowardRamp(factory, targetUnit, ramp)\n    if not targetUnit or not ramp then\n        return\n    end\n\n    if ramp.headingDegrees then\n        local orientation = Engine.EulerToQuaternion(\n            EngineClasses.float3(0, math.rad(ramp.headingDegrees), 0),\n            RotationOrder.Default\n        )\n        Engine.SetGlobalEntityLocalRotation(targetUnit.id, orientation)\n        return\n    end\n\n    local unitPosition = targetUnit:GetPosition()\n    local rampPosition = GetCybranFactoryRollOffRampPosition(factory, ramp.rampOffset)\n    local forward = EngineClasses.float3(\n        rampPosition.x - unitPosition.x,\n        0,\n        rampPosition.z - unitPosition.z\n    )\n    if forward.x == 0 and forward.z == 0 then\n        return\n    end\n\n    local orientation = EngineClasses.quaternion()\n    Engine.QuaternionLookRotation(\n        math3D.normalize(forward),\n        EngineClasses.float3(0, 1, 0),\n        orientation\n    )\n    Engine.SetGlobalEntityLocalRotation(targetUnit.id, orientation)\nend\n\nlocal function PrepareCybranFactoryRollOff(factory, targetUnit)\n    if not targetUnit or not targetUnit:HasTags(Tags.MOBILE) then\n        return\n    end\n    FaceCybranFactoryUnitTowardRamp(factory, targetUnit, SelectCybranFactoryRollOffRamp(factory, targetUnit))\nend\n\nlocal function CybranFactoryUnitIsAlive(unit)\n    return unit ~= nil and not unit.dead and not unit.deleted\nend\n\nlocal function GetCybranFactoryClearancePoint(factory, ramp)\n    if not ramp then\n        return nil\n    end\n\n    local clearancePosition = GetCybranFactoryRollOffRampPosition(\n        factory,\n        ramp.clearanceOffset or ramp.rampOffset\n    )\n    local _, terrainHeight = Engine.SampleTerrainHeight(\n        EngineClasses.float3(clearancePosition.x, 0, clearancePosition.z)\n    )\n    return EngineClasses.float3(clearancePosition.x, terrainHeight, clearancePosition.z)\nend\n\nfunction GuardCybranLandFactory:StopBuildColliderPin(targetUnit)\n    if targetUnit ~= nil and self.guardCybranPinnedBuildTarget ~= targetUnit then\n        return\n    end\n\n    local pinnedTarget = self.guardCybranPinnedBuildTarget\n    self.guardCybranPinnedBuildTarget = nil\n    if pinnedTarget and pinnedTarget.scoFactoryColliderPinOwner == self then\n        pinnedTarget.scoFactoryColliderPinOwner = nil\n    end\nend\n\nfunction GuardCybranLandFactory:PinBuildCollider(targetUnit)\n    self:StopBuildColliderPin()\n    if not CybranFactoryUnitIsAlive(targetUnit)\n        or not targetUnit:HasTags(Tags.MOBILE)\n        or targetUnit:IsCompleted()\n    then\n        return\n    end\n\n    self.guardCybranPinnedBuildTarget = targetUnit\n    targetUnit.scoFactoryColliderPinOwner = self\n    Engine.SetVolumeColliderEnabled(targetUnit.id, false)\nend\n\nfunction GuardCybranLandFactory:ReleaseBuiltUnit(targetUnit, ramp)\n    if not CybranFactoryUnitIsAlive(targetUnit)\n        or not targetUnit:HasTags(Tags.MOBILE)\n        or not targetUnit:IsCompleted()\n    then\n        return false\n    end\n\n    local clearancePoint = GetCybranFactoryClearancePoint(self, ramp)\n    if not clearancePoint then\n        return false\n    end\n\n    -- Relocate before collision returns. Enabling it at the staging point\n    -- allows the finished unit to intersect, sink through, or roll through\n    -- the converted factory hull.\n    FaceCybranFactoryUnitTowardRamp(self, targetUnit, ramp)\n    targetUnit:SetPosition(clearancePoint)\n    self:StopBuildColliderPin(targetUnit)\n    if CybranFactoryUnitIsAlive(targetUnit) then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, true)\n    end\n    return true\nend\n\nfunction GuardCybranLandFactory:OnStartBuildRoutine(targetUnit)\n    self:PinBuildCollider(targetUnit)\n    GuardLandFactory.OnStartBuildRoutine(self, targetUnit)\n    PrepareCybranFactoryRollOff(self, targetUnit)\n    if CybranFactoryUnitIsAlive(targetUnit)\n        and targetUnit:HasTags(Tags.MOBILE)\n        and not targetUnit:IsCompleted()\n    then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, false)\n    end\n    local animations = self.tp.visuals and self.tp.visuals.animations\n    if animations and animations.build then\n        Engine.PlayAnimation(self.id, animations.build.id, 0.1)\n    end\nend\n\nfunction GuardCybranLandFactory:OnStopBuildRoutine(targetUnit)\n    local completed = CybranFactoryUnitIsAlive(targetUnit) and targetUnit:IsCompleted()\n    if completed then\n        -- The base callback notifies clients and restores local collision,\n        -- so the host must put a completed child clear of the hull first.\n        self:ReleaseBuiltUnit(targetUnit, SelectCybranFactoryRollOffRamp(self, targetUnit))\n    elseif CybranFactoryUnitIsAlive(targetUnit) and targetUnit:HasTags(Tags.MOBILE) then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, false)\n    end\n    GuardLandFactory.OnStopBuildRoutine(self, targetUnit)\n    local animations = self.tp.visuals and self.tp.visuals.animations\n    if animations and animations.walk then\n        Engine.PlayAnimation(self.id, animations.walk.id, 0.1)\n    end\nend\n\nfunction GuardCybranLandFactory:RollOffUnit(targetUnit)\n    local ramp = SelectCybranFactoryRollOffRamp(self, targetUnit)\n    if not ramp then\n        GuardLandFactory.RollOffUnit(self, targetUnit)\n        return\n    end\n\n    FaceCybranFactoryUnitTowardRamp(self, targetUnit, ramp)\n    local rampPosition = GetCybranFactoryRollOffRampPosition(self, ramp.rampOffset)\n    local clearancePosition = GetCybranFactoryRollOffRampPosition(self, ramp.clearanceOffset or ramp.rampOffset)\n    local released = self:ReleaseBuiltUnit(targetUnit, ramp)\n    if not released then\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, false, rampPosition, nil)\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, true, clearancePosition, nil)\n    end\n\n    local source = self.unitBeingBuiltSource or self\n    if source.rallyPoint then\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, true, source.rallyPoint, nil)\n    end\n\n    local key = GetCybranFactoryRollOffTargetKey(targetUnit)\n    if key and self.guardCybranRollOffRampIndexes then\n        self.guardCybranRollOffRampIndexes[key] = nil\n    end\nend\n\nfunction GuardCybranLandFactory:ProductionBehaviorStop()\n    local targetUnit = self.productionBehaviorTargetUnit\n    self:StopBuildColliderPin(targetUnit)\n    GuardLandFactory.ProductionBehaviorStop(self)\nend\n\nfunction GuardCybranLandFactory:OnCancelConstruction()\n    self:StopBuildColliderPin()\n    GuardLandFactory.OnCancelConstruction(self)\nend\n\n-- The factory's 6x6 art core is its real model footprint. Two separate\n-- Default-grid roots protect the angled left and right roll-off lanes.\n-- Each root avoids the engine's one-grid-modifier-per-prefab-root\n-- limitation and deliberately has no navmap modifier.\nlocal PlacementLayer = Import(\"common/layers.lua\").PlacementLayer\nlocal CybranFactoryRollOffReservationPrefabID = nil\n_G.SupremeCommanderOverhaulFactoryReservationOwners = _G.SupremeCommanderOverhaulFactoryReservationOwners or {}\n\nlocal function OverhaulFactoryReservationKey(id)\n    return tostring(id.index) .. \":\" .. tostring(id.version)\nend\n\nlocal function GetCybranFactoryRollOffReservationPrefabID()\n    if CybranFactoryRollOffReservationPrefabID then\n        return CybranFactoryRollOffReservationPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulCybranFactoryRollOffGlobal\")\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n    table.insert(prefab.globalTemplate.gridModifierTemplates, EngineClasses.GridModifierTemplate(\n        TemplateHeadEntityName,\n        EngineClasses.int2(0, 0),\n        EngineClasses.int2(0, 0),\n        _G.globalBuildingPlacementGridID,\n        PlacementLayer.Default,\n        PlacementLayer.None,\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the Cybran factory roll-off reservation prefab.\")\n        return nil\n    end\n\n    CybranFactoryRollOffReservationPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetCybranFactoryRollOffReservations(factory)\n    local additions = factory.tp.additions\n    return additions and additions.placementReservations or {}\nend\n\nlocal function DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n    for _, reservationID in ipairs(reservationIDs or {}) do\n        _G.SupremeCommanderOverhaulFactoryReservationOwners[OverhaulFactoryReservationKey(reservationID)] = nil\n        if Engine.IsValidGlobalID(reservationID) then\n            Engine.SetGlobalGridModifierEnabled(reservationID, false)\n            Engine.DeletePrefabInstance(reservationID)\n        end\n    end\nend\n\nfunction GuardCybranLandFactory:CreateRollOffReservation()\n    if self.guardCybranRollOffReservationIDs then\n        return\n    end\n\n    local reservations = GetCybranFactoryRollOffReservations(self)\n    if #reservations == 0 then\n        return\n    end\n\n    local prefabID = GetCybranFactoryRollOffReservationPrefabID()\n    if not prefabID then\n        return\n    end\n\n    local reservationIDs = {}\n    local factoryPosition = self:GetPosition()\n    for _, reservation in ipairs(reservations) do\n        local size = reservation.size\n        if not size then\n            DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Cybran factory roll-off reservation is missing a size.\")\n            return\n        end\n\n        local offset = reservation.offset or {}\n        local position = EngineClasses.float3(\n            factoryPosition.x + (offset.x or 0),\n            factoryPosition.y + (offset.y or 0),\n            factoryPosition.z + (offset.z or 0)\n        )\n        local errorCode, reservationID = Engine.InstantiatePrefab(\n            prefabID,\n            position,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidGlobalID(reservationID) then\n            if Engine.IsValidGlobalID(reservationID) then\n                Engine.DeletePrefabInstance(reservationID)\n            end\n            DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Unable to create a Cybran factory roll-off reservation.\")\n            return\n        end\n\n        Engine.SetGlobalGridModifierSize(reservationID, EngineClasses.float2(size.x, size.y))\n        table.insert(reservationIDs, reservationID)\n    end\n\n    self.guardCybranRollOffReservationIDs = reservationIDs\n    for _, reservationID in ipairs(reservationIDs) do\n        _G.SupremeCommanderOverhaulFactoryReservationOwners[OverhaulFactoryReservationKey(reservationID)] = self.id\n        Engine.SetGlobalGridModifierEnabled(reservationID, true)\n    end\nend\n\nfunction GuardCybranLandFactory:DestroyRollOffReservation()\n    DestroyCybranFactoryRollOffReservationIDs(self.guardCybranRollOffReservationIDs)\n    self.guardCybranRollOffReservationIDs = nil\nend\n\nfunction GuardCybranLandFactory:PromoteToUnit()\n    GuardLandFactory.PromoteToUnit(self)\n    self:CreateRollOffReservation()\nend\n\nfunction GuardCybranLandFactory:OnDestroy(isDelete)\n    self:StopBuildColliderPin()\n    self:DestroyRollOffReservation()\n    GuardLandFactory.OnDestroy(self, isDelete)\nend"),
		new PatchSpec("LJ/lua/client/units/unitsClasses/unitsDefaultGuard.lua", "Guard client unit classes", "\nlocal CreateConstructionBeam = Import(\"client/entities/constructionBeam.lua\").CreateConstructionBeam\nlocal PlacementLayer = Import(\"common/layers.lua\").PlacementLayer\n\nlocal CybranFactoryConstructionBeamPrefabID = nil\nlocal CybranFactoryRollOffReservationPrefabID = nil\nlocal CybranFactoryConstructionBeamGroup = {}\nCybranFactoryConstructionBeamGroup.__index = CybranFactoryConstructionBeamGroup\n\nlocal function GetCybranFactoryConstructionBeamPrefabID()\n    if CybranFactoryConstructionBeamPrefabID then\n        return CybranFactoryConstructionBeamPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulCybranFactoryConstructionBeam\")\n\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n\n    local beamEntity = EngineClasses.EntityTemplate()\n    beamEntity.entityName = \"Construction Beam\"\n    beamEntity.parentEntityName = TemplateHeadEntityName\n    beamEntity.localTranslation = EngineClasses.float3(0, 0, 0)\n    beamEntity.localScale = 1\n    beamEntity.localRotation = GetIdentityQuaternion()\n    beamEntity.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, beamEntity)\n\n    table.insert(prefab.localTemplate.meshTemplates, EngineClasses.MeshTemplate(\n        \"Construction Beam\",\n        \"VFX/Models/Static/ConstructionBeam.sanmodel\",\n        \"VFX/Materials/ConstructionBeams/Guard_ConstructionBeam.sanmaterial\",\n        EngineClasses.float3(0.05, 1, 1),\n        ShadowCastingMode.Off,\n        EngineClasses.float4(),\n        EngineClasses.float4(),\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the Cybran factory construction-beam prefab.\")\n        return nil\n    end\n\n    CybranFactoryConstructionBeamPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetCybranFactoryRollOffReservationPrefabID()\n    if CybranFactoryRollOffReservationPrefabID then\n        return CybranFactoryRollOffReservationPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulCybranFactoryRollOffLocal\")\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n    table.insert(prefab.localTemplate.localGridModifierTemplates, EngineClasses.GridModifierTemplate(\n        TemplateHeadEntityName,\n        EngineClasses.int2(0, 0),\n        EngineClasses.int2(0, 0),\n        _G.localBuildingPlacementGridID,\n        PlacementLayer.Default,\n        PlacementLayer.None,\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the Cybran factory local roll-off reservation prefab.\")\n        return nil\n    end\n\n    CybranFactoryRollOffReservationPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetCybranFactoryRollOffReservations(factory)\n    local additions = factory.tp.additions\n    return additions and additions.placementReservations or {}\nend\n\nlocal function DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n    for _, reservationID in ipairs(reservationIDs or {}) do\n        if Engine.IsValidLocalID(reservationID) then\n            Engine.SetLocalGridModifierEnabled(reservationID, false)\n            Engine.DeletePrefabInstance(reservationID)\n        end\n    end\nend\n\nfunction CybranFactoryConstructionBeamGroup:SetTarget(target)\n    if self.deleted then\n        return\n    end\n\n    if target == nil then\n        self:RemoveTarget()\n        return\n    end\n\n    for _, state in ipairs(self.beams) do\n        -- ConstructionBeam owns the target's collision-center/progress\n        -- interpolation. Passing the factory floor here made every arm\n        -- aim backward/down into the imported structure instead.\n        state.beam:SetTarget(target)\n    end\n    self:RenderUpdate()\nend\n\nfunction CybranFactoryConstructionBeamGroup:RemoveTarget()\n    self.enabled = false\n    for _, state in ipairs(self.beams) do\n        -- A detached loose root otherwise retains its default visible\n        -- mesh when an intel event arrives after build completion.\n        state.beam:SetEnabled(false)\n        state.beam:RemoveTarget()\n    end\nend\n\nfunction CybranFactoryConstructionBeamGroup:SetEnabled(enabled)\n    if self.deleted then\n        return\n    end\n    self.enabled = enabled == true\n    for _, state in ipairs(self.beams) do\n        state.beam:SetEnabled(self.enabled and state.beam.targetUnit ~= nil)\n    end\n    self:RenderUpdate()\nend\n\nfunction CybranFactoryConstructionBeamGroup:Update()\n    -- Unit:BuildThread invokes constructionBeam:Update() every simulation\n    -- tick. Loose visual roots are render-only, so that loop must not\n    -- duplicate per-arm FFI work or allocations.\nend\n\nfunction CybranFactoryConstructionBeamGroup:RenderUpdate()\n    if self.deleted or not self.enabled then\n        return\n    end\n    for _, state in ipairs(self.beams) do\n        if state.beam.targetUnit ~= nil\n            and Engine.IsValidLocalID(state.rootID)\n            and Engine.IsValidLocalID(state.muzzleID) then\n            Engine.GetLocalEntityWorldPosition(state.muzzleID, state.muzzlePosition)\n            Engine.SetLocalEntityLocalPosition(state.rootID, state.muzzlePosition)\n            state.beam:Update()\n        end\n    end\nend\n\nfunction CybranFactoryConstructionBeamGroup:Delete()\n    if self.deleted then\n        return\n    end\n    self.deleted = true\n    self.enabled = false\n\n    for _, state in ipairs(self.beams) do\n        state.beam:SetEnabled(false)\n        state.beam:RemoveTarget()\n        if Engine.IsValidLocalID(state.rootID) then\n            Engine.DeletePrefabInstance(state.rootID)\n        end\n    end\n    self.beams = {}\nend\n\nlocal function CreateCybranFactoryConstructionBeamGroup(factory, boneNames)\n    local prefabID = GetCybranFactoryConstructionBeamPrefabID()\n    if not prefabID then\n        return nil\n    end\n\n    local group = setmetatable({\n        beams = {},\n        deleted = false,\n        enabled = false,\n    }, CybranFactoryConstructionBeamGroup)\n    local initialPosition = factory:GetPosition()\n    for _, boneName in ipairs(boneNames) do\n        local muzzleID = factory:GetBoneId(boneName)\n        if not Engine.IsValidLocalID(muzzleID) then\n            group:Delete()\n            Engine.Error(\"Cybran factory is missing construction-beam bone \" .. boneName .. \".\")\n            return nil\n        end\n\n        local errorCode, rootID = Engine.InstantiatePrefab(\n            prefabID,\n            initialPosition,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidLocalID(rootID) then\n            if Engine.IsValidLocalID(rootID) then\n                Engine.DeletePrefabInstance(rootID)\n            end\n            group:Delete()\n            Engine.Error(\"Unable to instantiate a Cybran factory construction beam for \" .. boneName .. \".\")\n            return nil\n        end\n\n        local beamEntityID = EngineClasses.LocalID()\n        Engine.GetLocalBone(rootID, \"Construction Beam\", beamEntityID)\n        if not Engine.IsValidLocalID(beamEntityID) then\n            Engine.DeletePrefabInstance(rootID)\n            group:Delete()\n            Engine.Error(\"The Cybran factory construction-beam prefab has no renderer entity.\")\n            return nil\n        end\n\n        table.insert(group.beams, {\n            rootID = rootID,\n            muzzleID = muzzleID,\n            muzzlePosition = EngineClasses.float3(),\n            beam = CreateConstructionBeam(rootID),\n        })\n    end\n\n    return group\nend\n\nlocal function DisposeCybranFactoryConstructionBeam(factory)\n    local beam = factory.constructionBeam\n    factory.constructionBeam = nil\n    factory.constructionBeamEnabled = false\n    if beam and beam.Delete then\n        beam:Delete()\n    end\nend\n\n-- The client owns cosmetic tarmac and beams plus local grid reservations\n-- for both angled factory roll-off lanes.\nlocal GuardLandFactory = ClientGuardLandFactory or GuardLandFactory\nif not GuardLandFactory then\n    error(\"SCO could not resolve the client Guard land-factory base class.\")\nend\nClientGuardCybranLandFactory = Class(\"GuardCybranLandFactory\", GuardLandFactory)\nlocal GuardCybranLandFactory = ClientGuardCybranLandFactory\n\nfunction GuardCybranLandFactory:CreateTarmac()\n    local tarmacSize = self.tp.additions and self.tp.additions.tarmacSize\n    if not tarmacSize or not _G.TarmacGuardPrefabID then\n        return\n    end\n\n    self.tarmac = self:CreateDecal(_G.TarmacGuardPrefabID, tarmacSize.x, tarmacSize.y, 0)\n    if self.tarmac then\n        self.tarmac:SetEnabled(false)\n    end\nend\n\nfunction GuardCybranLandFactory:CreateRollOffReservation()\n    if self.guardCybranRollOffReservationIDs or self:IsPlacementGhost() then\n        return\n    end\n\n    local reservations = GetCybranFactoryRollOffReservations(self)\n    if #reservations == 0 then\n        return\n    end\n\n    local prefabID = GetCybranFactoryRollOffReservationPrefabID()\n    if not prefabID then\n        return\n    end\n\n    local reservationIDs = {}\n    local factoryPosition = self:GetPosition()\n    for _, reservation in ipairs(reservations) do\n        local size = reservation.size\n        if not size then\n            DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Cybran factory local roll-off reservation is missing a size.\")\n            return\n        end\n\n        local offset = reservation.offset or {}\n        local position = EngineClasses.float3(\n            factoryPosition.x + (offset.x or 0),\n            factoryPosition.y + (offset.y or 0),\n            factoryPosition.z + (offset.z or 0)\n        )\n        local errorCode, reservationID = Engine.InstantiatePrefab(\n            prefabID,\n            position,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidLocalID(reservationID) then\n            if Engine.IsValidLocalID(reservationID) then\n                Engine.DeletePrefabInstance(reservationID)\n            end\n            DestroyCybranFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Unable to create a Cybran factory local roll-off reservation.\")\n            return\n        end\n\n        Engine.SetLocalGridModifierSize(reservationID, EngineClasses.float2(size.x, size.y))\n        table.insert(reservationIDs, reservationID)\n    end\n\n    self.guardCybranRollOffReservationIDs = reservationIDs\n    self:SetRollOffReservationEnabled(self:IsIntelVisionVisible())\nend\n\nfunction GuardCybranLandFactory:SetRollOffReservationEnabled(enabled)\n    for _, reservationID in ipairs(self.guardCybranRollOffReservationIDs or {}) do\n        if Engine.IsValidLocalID(reservationID) then\n            Engine.SetLocalGridModifierEnabled(reservationID, enabled)\n        end\n    end\nend\n\nfunction GuardCybranLandFactory:DestroyRollOffReservation()\n    DestroyCybranFactoryRollOffReservationIDs(self.guardCybranRollOffReservationIDs)\n    self.guardCybranRollOffReservationIDs = nil\nend\n\nfunction GuardCybranLandFactory:__init(globalId, localId, armyId, template, progress)\n    GuardLandFactory.__init(self, globalId, localId, armyId, template, progress)\n    if not self:IsPlacementGhost() then\n        self:CreateRollOffReservation()\n    end\nend\n\nfunction GuardCybranLandFactory:OnPromoteToUnit()\n    self:CreateRollOffReservation()\n    GuardLandFactory.OnPromoteToUnit(self)\nend\n\nfunction GuardCybranLandFactory:OnIntelHidden()\n    GuardLandFactory.OnIntelHidden(self)\n    self:SetRollOffReservationEnabled(false)\nend\n\nfunction GuardCybranLandFactory:OnIntelVision()\n    GuardLandFactory.OnIntelVision(self)\n    self:CreateRollOffReservation()\n    self:SetRollOffReservationEnabled(true)\nend\n\nfunction GuardCybranLandFactory:SetUpConstructionBeam()\n    DisposeCybranFactoryConstructionBeam(self)\n    local boneNames = self.tp.additions and self.tp.additions.buildBeamBones\n    if boneNames and #boneNames > 0 then\n        self.constructionBeam = CreateCybranFactoryConstructionBeamGroup(self, boneNames)\n    end\nend\n\nfunction GuardCybranLandFactory:OnStartBuildRoutine(buildableId)\n    self:SetUpConstructionBeam()\n    GuardLandFactory.OnStartBuildRoutine(self, buildableId)\nend\n\nfunction GuardCybranLandFactory:ClientOnStopBuilding()\n    GuardLandFactory.ClientOnStopBuilding(self)\n    DisposeCybranFactoryConstructionBeam(self)\nend\n\nfunction GuardCybranLandFactory:OnEndUpgrading(upgrade)\n    GuardLandFactory.OnEndUpgrading(self, upgrade)\n    DisposeCybranFactoryConstructionBeam(self)\nend\n\nfunction GuardCybranLandFactory:RenderUpdateBeams()\n    GuardLandFactory.RenderUpdateBeams(self)\n    if self.constructionBeam then\n        self.constructionBeam:RenderUpdate()\n    end\nend\n\nfunction GuardCybranLandFactory:OnIntelRadar()\n    GuardLandFactory.OnIntelRadar(self)\n    self:RecalculateConstructionBeamState()\n    self:SetRollOffReservationEnabled(false)\nend\n\nfunction GuardCybranLandFactory:OnDestroy(isDelete)\n    self:DestroyRollOffReservation()\n    DisposeCybranFactoryConstructionBeam(self)\n    GuardLandFactory.OnDestroy(self, isDelete)\nend\n\nfunction GuardCybranLandFactory:OnDelete()\n    self:DestroyRollOffReservation()\n    DisposeCybranFactoryConstructionBeam(self)\n    GuardLandFactory.OnDelete(self)\nend"),
		new PatchSpec("LJ/lua/host/units/unitsClasses/unitsDefaultEDA.lua", "EDA UEF factory host unit classes", "\nlocal OrderTasks = Import(\"common/commonOrders.lua\").OrderTasks\nlocal HostOrderManager = Import(\"host/managers/orders/hostOrderManager.lua\")\n\n-- UEF factory rigs are static Sanctuary rigs. The native EDA factory\n-- behavior stays authoritative; only its build staging and extra exit\n-- reservation are adapted to the imported model.\nlocal EDALandFactory = HostEDALandFactory or EDALandFactory\nif not EDALandFactory then\n    error(\"SCO could not resolve the host EDA land-factory base class.\")\nend\nHostEDAUefLandFactory = Class(\"EDAUefLandFactory\", EDALandFactory)\nlocal EDAUefLandFactory = HostEDAUefLandFactory\n\nfunction EDAUefLandFactory:UpdateAnimations()\n    -- Static factories have no Movement component. The personal UEF\n    -- factory contract intentionally registers no walk/run animations.\nend\n\nfunction EDAUefLandFactory:GetRollOffPoint()\n    local offset = self.tp.additions and self.tp.additions.buildStagingOffset\n    if not offset then\n        return EDALandFactory.GetRollOffPoint(self)\n    end\n\n    local point = self:GetPosition()\n    point.x = point.x + offset.x\n    point.y = point.y + offset.y\n    point.z = point.z + offset.z\n    return point\nend\n\nlocal function GetEdaUefFactoryRollOffRamps(factory)\n    local additions = factory.tp.additions\n    return additions and additions.rollOffRamps\nend\n\nlocal function GetEdaUefFactoryRollOffRampPosition(factory, offset)\n    local factoryPosition = factory:GetPosition()\n    return EngineClasses.float3(\n        factoryPosition.x + (offset.x or 0),\n        factoryPosition.y + (offset.y or 0),\n        factoryPosition.z + (offset.z or 0)\n    )\nend\n\nlocal function GetEdaUefFactoryRollOffTargetKey(targetUnit)\n    local id = targetUnit and targetUnit.id\n    if not id then\n        return nil\n    end\n    return tostring(id.index) .. \":\" .. tostring(id.version)\nend\n\nlocal function SelectEdaUefFactoryRollOffRamp(factory, targetUnit)\n    local ramps = GetEdaUefFactoryRollOffRamps(factory)\n    if not ramps or #ramps == 0 then\n        return nil\n    end\n\n    local key = GetEdaUefFactoryRollOffTargetKey(targetUnit)\n    local selectedIndexes = factory.edaUefRollOffRampIndexes\n    local selectedIndex = key and selectedIndexes and selectedIndexes[key]\n    if selectedIndex then\n        return ramps[selectedIndex]\n    end\n\n    local source = factory.unitBeingBuiltSource or factory\n    local rallyPoint = source.rallyPoint\n    if rallyPoint then\n        local closestDistanceSquared = nil\n        for index, ramp in ipairs(ramps) do\n            local clearancePosition = GetEdaUefFactoryRollOffRampPosition(factory, ramp.clearanceOffset or ramp.rampOffset)\n            local deltaX = clearancePosition.x - rallyPoint.x\n            local deltaZ = clearancePosition.z - rallyPoint.z\n            local distanceSquared = (deltaX * deltaX) + (deltaZ * deltaZ)\n            if not closestDistanceSquared or distanceSquared < closestDistanceSquared then\n                closestDistanceSquared = distanceSquared\n                selectedIndex = index\n            end\n        end\n    else\n        selectedIndex = factory.edaUefNextRollOffRampIndex or 1\n        if selectedIndex < 1 or selectedIndex > #ramps then\n            selectedIndex = 1\n        end\n        factory.edaUefNextRollOffRampIndex = selectedIndex + 1\n        if factory.edaUefNextRollOffRampIndex > #ramps then\n            factory.edaUefNextRollOffRampIndex = 1\n        end\n    end\n\n    if key then\n        factory.edaUefRollOffRampIndexes = selectedIndexes or {}\n        factory.edaUefRollOffRampIndexes[key] = selectedIndex\n    end\n    return ramps[selectedIndex]\nend\n\nlocal function FaceEdaUefFactoryUnitTowardRamp(factory, targetUnit, ramp)\n    if not targetUnit or not ramp then\n        return\n    end\n\n    if ramp.headingDegrees then\n        local orientation = Engine.EulerToQuaternion(\n            EngineClasses.float3(0, math.rad(ramp.headingDegrees), 0),\n            RotationOrder.Default\n        )\n        Engine.SetGlobalEntityLocalRotation(targetUnit.id, orientation)\n        return\n    end\n\n    local unitPosition = targetUnit:GetPosition()\n    local rampPosition = GetEdaUefFactoryRollOffRampPosition(factory, ramp.rampOffset)\n    local forward = EngineClasses.float3(\n        rampPosition.x - unitPosition.x,\n        0,\n        rampPosition.z - unitPosition.z\n    )\n    if forward.x == 0 and forward.z == 0 then\n        return\n    end\n\n    local orientation = EngineClasses.quaternion()\n    Engine.QuaternionLookRotation(\n        math3D.normalize(forward),\n        EngineClasses.float3(0, 1, 0),\n        orientation\n    )\n    Engine.SetGlobalEntityLocalRotation(targetUnit.id, orientation)\nend\n\nlocal function PrepareEdaUefFactoryRollOff(factory, targetUnit)\n    if not targetUnit or not targetUnit:HasTags(Tags.MOBILE) then\n        return\n    end\n    FaceEdaUefFactoryUnitTowardRamp(factory, targetUnit, SelectEdaUefFactoryRollOffRamp(factory, targetUnit))\nend\n\nlocal function EdaUefFactoryUnitIsAlive(unit)\n    return unit ~= nil and not unit.dead and not unit.deleted\nend\n\nlocal function GetEdaUefFactoryClearancePoint(factory, ramp)\n    if not ramp then\n        return nil\n    end\n\n    local clearancePosition = GetEdaUefFactoryRollOffRampPosition(\n        factory,\n        ramp.clearanceOffset or ramp.rampOffset\n    )\n    local _, terrainHeight = Engine.SampleTerrainHeight(\n        EngineClasses.float3(clearancePosition.x, 0, clearancePosition.z)\n    )\n    return EngineClasses.float3(clearancePosition.x, terrainHeight, clearancePosition.z)\nend\n\nfunction EDAUefLandFactory:StopBuildColliderPin(targetUnit)\n    if targetUnit ~= nil and self.edaUefPinnedBuildTarget ~= targetUnit then\n        return\n    end\n\n    local pinnedTarget = self.edaUefPinnedBuildTarget\n    self.edaUefPinnedBuildTarget = nil\n    if pinnedTarget and pinnedTarget.scoFactoryColliderPinOwner == self then\n        pinnedTarget.scoFactoryColliderPinOwner = nil\n    end\nend\n\nfunction EDAUefLandFactory:PinBuildCollider(targetUnit)\n    self:StopBuildColliderPin()\n    if not EdaUefFactoryUnitIsAlive(targetUnit)\n        or not targetUnit:HasTags(Tags.MOBILE)\n        or targetUnit:IsCompleted()\n    then\n        return\n    end\n\n    self.edaUefPinnedBuildTarget = targetUnit\n    targetUnit.scoFactoryColliderPinOwner = self\n    Engine.SetVolumeColliderEnabled(targetUnit.id, false)\nend\n\nfunction EDAUefLandFactory:ReleaseBuiltUnit(targetUnit, ramp)\n    if not EdaUefFactoryUnitIsAlive(targetUnit)\n        or not targetUnit:HasTags(Tags.MOBILE)\n        or not targetUnit:IsCompleted()\n    then\n        return false\n    end\n\n    local clearancePoint = GetEdaUefFactoryClearancePoint(self, ramp)\n    if not clearancePoint then\n        return false\n    end\n\n    -- Relocate before collision returns. Enabling it at the staging point\n    -- allows the finished unit to intersect, sink through, or roll through\n    -- the converted factory hull.\n    FaceEdaUefFactoryUnitTowardRamp(self, targetUnit, ramp)\n    targetUnit:SetPosition(clearancePoint)\n    self:StopBuildColliderPin(targetUnit)\n    if EdaUefFactoryUnitIsAlive(targetUnit) then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, true)\n    end\n    return true\nend\n\nfunction EDAUefLandFactory:OnStartBuildRoutine(targetUnit)\n    self:PinBuildCollider(targetUnit)\n    EDALandFactory.OnStartBuildRoutine(self, targetUnit)\n    PrepareEdaUefFactoryRollOff(self, targetUnit)\n    if EdaUefFactoryUnitIsAlive(targetUnit)\n        and targetUnit:HasTags(Tags.MOBILE)\n        and not targetUnit:IsCompleted()\n    then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, false)\n    end\nend\n\nfunction EDAUefLandFactory:OnStopBuildRoutine(targetUnit)\n    local completed = EdaUefFactoryUnitIsAlive(targetUnit) and targetUnit:IsCompleted()\n    if completed then\n        -- The base callback notifies clients and restores local collision,\n        -- so the host must put a completed child clear of the hull first.\n        self:ReleaseBuiltUnit(targetUnit, SelectEdaUefFactoryRollOffRamp(self, targetUnit))\n    elseif EdaUefFactoryUnitIsAlive(targetUnit) and targetUnit:HasTags(Tags.MOBILE) then\n        Engine.SetVolumeColliderEnabled(targetUnit.id, false)\n    end\n    EDALandFactory.OnStopBuildRoutine(self, targetUnit)\nend\n\nfunction EDAUefLandFactory:RollOffUnit(targetUnit)\n    local ramp = SelectEdaUefFactoryRollOffRamp(self, targetUnit)\n    if not ramp then\n        EDALandFactory.RollOffUnit(self, targetUnit)\n        return\n    end\n\n    FaceEdaUefFactoryUnitTowardRamp(self, targetUnit, ramp)\n    local rampPosition = GetEdaUefFactoryRollOffRampPosition(self, ramp.rampOffset)\n    local clearancePosition = GetEdaUefFactoryRollOffRampPosition(self, ramp.clearanceOffset or ramp.rampOffset)\n    local released = self:ReleaseBuiltUnit(targetUnit, ramp)\n    if not released then\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, false, rampPosition, nil)\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, true, clearancePosition, nil)\n    end\n\n    local source = self.unitBeingBuiltSource or self\n    if source.rallyPoint then\n        HostOrderManager.HostIssueOrder(OrderTasks.MOVE, {targetUnit}, true, source.rallyPoint, nil)\n    end\n\n    local key = GetEdaUefFactoryRollOffTargetKey(targetUnit)\n    if key and self.edaUefRollOffRampIndexes then\n        self.edaUefRollOffRampIndexes[key] = nil\n    end\nend\n\nfunction EDAUefLandFactory:ProductionBehaviorStop()\n    local targetUnit = self.productionBehaviorTargetUnit\n    self:StopBuildColliderPin(targetUnit)\n    EDALandFactory.ProductionBehaviorStop(self)\nend\n\nfunction EDAUefLandFactory:OnCancelConstruction()\n    self:StopBuildColliderPin()\n    EDALandFactory.OnCancelConstruction(self)\nend\n\n-- The 6x6 art core uses the normal factory grid modifier. Two distinct\n-- 6x4 roots protect the left and right UEF roll-off lanes.\nlocal PlacementLayer = Import(\"common/layers.lua\").PlacementLayer\nlocal EdaUefFactoryRollOffReservationPrefabID = nil\n_G.SupremeCommanderOverhaulFactoryReservationOwners = _G.SupremeCommanderOverhaulFactoryReservationOwners or {}\n\nlocal function OverhaulFactoryReservationKey(id)\n    return tostring(id.index) .. \":\" .. tostring(id.version)\nend\n\nlocal function GetEdaUefFactoryRollOffReservationPrefabID()\n    if EdaUefFactoryRollOffReservationPrefabID then\n        return EdaUefFactoryRollOffReservationPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulEdaUefFactoryRollOffGlobal\")\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n    table.insert(prefab.globalTemplate.gridModifierTemplates, EngineClasses.GridModifierTemplate(\n        TemplateHeadEntityName,\n        EngineClasses.int2(0, 0),\n        EngineClasses.int2(0, 0),\n        _G.globalBuildingPlacementGridID,\n        PlacementLayer.Default,\n        PlacementLayer.None,\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the EDA UEF factory roll-off reservation prefab.\")\n        return nil\n    end\n\n    EdaUefFactoryRollOffReservationPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetEdaUefFactoryRollOffReservations(factory)\n    local additions = factory.tp.additions\n    return additions and additions.placementReservations or {}\nend\n\nlocal function DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n    for _, reservationID in ipairs(reservationIDs or {}) do\n        _G.SupremeCommanderOverhaulFactoryReservationOwners[OverhaulFactoryReservationKey(reservationID)] = nil\n        if Engine.IsValidGlobalID(reservationID) then\n            Engine.SetGlobalGridModifierEnabled(reservationID, false)\n            Engine.DeletePrefabInstance(reservationID)\n        end\n    end\nend\n\nfunction EDAUefLandFactory:CreateRollOffReservation()\n    if self.edaUefRollOffReservationIDs then\n        return\n    end\n\n    local reservations = GetEdaUefFactoryRollOffReservations(self)\n    if #reservations == 0 then\n        return\n    end\n\n    local prefabID = GetEdaUefFactoryRollOffReservationPrefabID()\n    if not prefabID then\n        return\n    end\n\n    local reservationIDs = {}\n    local factoryPosition = self:GetPosition()\n    for _, reservation in ipairs(reservations) do\n        local size = reservation.size\n        if not size then\n            DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"EDA UEF factory roll-off reservation is missing a size.\")\n            return\n        end\n\n        local offset = reservation.offset or {}\n        local position = EngineClasses.float3(\n            factoryPosition.x + (offset.x or 0),\n            factoryPosition.y + (offset.y or 0),\n            factoryPosition.z + (offset.z or 0)\n        )\n        local errorCode, reservationID = Engine.InstantiatePrefab(\n            prefabID,\n            position,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidGlobalID(reservationID) then\n            if Engine.IsValidGlobalID(reservationID) then\n                Engine.DeletePrefabInstance(reservationID)\n            end\n            DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Unable to create an EDA UEF factory roll-off reservation.\")\n            return\n        end\n\n        Engine.SetGlobalGridModifierSize(reservationID, EngineClasses.float2(size.x, size.y))\n        table.insert(reservationIDs, reservationID)\n    end\n\n    self.edaUefRollOffReservationIDs = reservationIDs\n    for _, reservationID in ipairs(reservationIDs) do\n        _G.SupremeCommanderOverhaulFactoryReservationOwners[OverhaulFactoryReservationKey(reservationID)] = self.id\n        Engine.SetGlobalGridModifierEnabled(reservationID, true)\n    end\nend\n\nfunction EDAUefLandFactory:DestroyRollOffReservation()\n    DestroyEdaUefFactoryRollOffReservationIDs(self.edaUefRollOffReservationIDs)\n    self.edaUefRollOffReservationIDs = nil\nend\n\nfunction EDAUefLandFactory:PromoteToUnit()\n    EDALandFactory.PromoteToUnit(self)\n    self:CreateRollOffReservation()\nend\n\nfunction EDAUefLandFactory:OnDestroy(isDelete)\n    self:StopBuildColliderPin()\n    self:DestroyRollOffReservation()\n    EDALandFactory.OnDestroy(self, isDelete)\nend"),
		new PatchSpec("LJ/lua/client/units/unitsClasses/unitsDefaultEDA.lua", "EDA UEF factory client unit classes", "\nlocal CreateConstructionBeam = Import(\"client/entities/constructionBeam.lua\").CreateConstructionBeam\nlocal PlacementLayer = Import(\"common/layers.lua\").PlacementLayer\n\nlocal EdaUefFactoryConstructionBeamPrefabID = nil\nlocal EdaUefFactoryRollOffReservationPrefabID = nil\nlocal EdaUefFactoryConstructionBeamGroup = {}\nEdaUefFactoryConstructionBeamGroup.__index = EdaUefFactoryConstructionBeamGroup\n\nlocal function GetEdaUefFactoryConstructionBeamPrefabID()\n    if EdaUefFactoryConstructionBeamPrefabID then\n        return EdaUefFactoryConstructionBeamPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulEdaUefFactoryConstructionBeam\")\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n\n    local beamEntity = EngineClasses.EntityTemplate()\n    beamEntity.entityName = \"Construction Beam\"\n    beamEntity.parentEntityName = TemplateHeadEntityName\n    beamEntity.localTranslation = EngineClasses.float3(0, 0, 0)\n    beamEntity.localScale = 1\n    beamEntity.localRotation = GetIdentityQuaternion()\n    beamEntity.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, beamEntity)\n\n    table.insert(prefab.localTemplate.meshTemplates, EngineClasses.MeshTemplate(\n        \"Construction Beam\",\n        \"VFX/Models/Static/ConstructionBeam.sanmodel\",\n        \"VFX/Materials/ConstructionBeams/EDA_ConstructionBeam.sanmaterial\",\n        EngineClasses.float3(0.05, 1, 1),\n        ShadowCastingMode.Off,\n        EngineClasses.float4(),\n        EngineClasses.float4(),\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the EDA UEF factory construction-beam prefab.\")\n        return nil\n    end\n\n    EdaUefFactoryConstructionBeamPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetEdaUefFactoryRollOffReservationPrefabID()\n    if EdaUefFactoryRollOffReservationPrefabID then\n        return EdaUefFactoryRollOffReservationPrefabID\n    end\n\n    local prefab = EngineClasses.PrefabTemplate(\"SupremeCommanderOverhaulEdaUefFactoryRollOffLocal\")\n    local head = EngineClasses.EntityTemplate()\n    head.entityName = TemplateHeadEntityName\n    head.localTranslation = EngineClasses.float3(0, 0, 0)\n    head.localScale = 1\n    head.localRotation = GetIdentityQuaternion()\n    head.forceSimulated = false\n    table.insert(prefab.hierarchyTemplate.entities, head)\n    table.insert(prefab.localTemplate.localGridModifierTemplates, EngineClasses.GridModifierTemplate(\n        TemplateHeadEntityName,\n        EngineClasses.int2(0, 0),\n        EngineClasses.int2(0, 0),\n        _G.localBuildingPlacementGridID,\n        PlacementLayer.Default,\n        PlacementLayer.None,\n        false\n    ))\n\n    local errorCode, prefabID = Engine.CreatePrefab(prefab)\n    if errorCode ~= EngineErrorCode.Success then\n        Engine.Error(\"Unable to create the EDA UEF factory local roll-off reservation prefab.\")\n        return nil\n    end\n\n    EdaUefFactoryRollOffReservationPrefabID = prefabID\n    return prefabID\nend\n\nlocal function GetEdaUefFactoryRollOffReservations(factory)\n    local additions = factory.tp.additions\n    return additions and additions.placementReservations or {}\nend\n\nlocal function DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n    for _, reservationID in ipairs(reservationIDs or {}) do\n        if Engine.IsValidLocalID(reservationID) then\n            Engine.SetLocalGridModifierEnabled(reservationID, false)\n            Engine.DeletePrefabInstance(reservationID)\n        end\n    end\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:SetTarget(target)\n    if self.deleted then\n        return\n    end\n\n    if target == nil then\n        self:RemoveTarget()\n        return\n    end\n\n    for _, state in ipairs(self.beams) do\n        -- ConstructionBeam owns the target's collision-center/progress\n        -- interpolation. Passing the factory floor here made every arm\n        -- aim backward/down into the imported structure instead.\n        state.beam:SetTarget(target)\n    end\n    self:RenderUpdate()\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:RemoveTarget()\n    self.enabled = false\n    for _, state in ipairs(self.beams) do\n        -- A detached loose root otherwise retains its default visible\n        -- mesh when an intel event arrives after build completion.\n        state.beam:SetEnabled(false)\n        state.beam:RemoveTarget()\n    end\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:SetEnabled(enabled)\n    if self.deleted then\n        return\n    end\n    self.enabled = enabled == true\n    for _, state in ipairs(self.beams) do\n        state.beam:SetEnabled(self.enabled and state.beam.targetUnit ~= nil)\n    end\n    self:RenderUpdate()\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:Update()\n    -- See the Cybran group: stock BuildThread owns this sim-rate call,\n    -- while loose root transforms must remain render-only.\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:RenderUpdate()\n    if self.deleted or not self.enabled then\n        return\n    end\n    for _, state in ipairs(self.beams) do\n        if state.beam.targetUnit ~= nil\n            and Engine.IsValidLocalID(state.rootID)\n            and Engine.IsValidLocalID(state.muzzleID) then\n            Engine.GetLocalEntityWorldPosition(state.muzzleID, state.muzzlePosition)\n            Engine.SetLocalEntityLocalPosition(state.rootID, state.muzzlePosition)\n            state.beam:Update()\n        end\n    end\nend\n\nfunction EdaUefFactoryConstructionBeamGroup:Delete()\n    if self.deleted then\n        return\n    end\n    self.deleted = true\n    self.enabled = false\n\n    for _, state in ipairs(self.beams) do\n        state.beam:SetEnabled(false)\n        state.beam:RemoveTarget()\n        if Engine.IsValidLocalID(state.rootID) then\n            Engine.DeletePrefabInstance(state.rootID)\n        end\n    end\n    self.beams = {}\nend\n\nlocal function CreateEdaUefFactoryConstructionBeamGroup(factory, boneNames)\n    local prefabID = GetEdaUefFactoryConstructionBeamPrefabID()\n    if not prefabID then\n        return nil\n    end\n\n    local group = setmetatable({\n        beams = {},\n        deleted = false,\n        enabled = false,\n    }, EdaUefFactoryConstructionBeamGroup)\n    local initialPosition = factory:GetPosition()\n    for _, boneName in ipairs(boneNames) do\n        local muzzleID = factory:GetBoneId(boneName)\n        if not Engine.IsValidLocalID(muzzleID) then\n            group:Delete()\n            Engine.Error(\"EDA UEF factory is missing construction-beam bone \" .. boneName .. \".\")\n            return nil\n        end\n\n        local errorCode, rootID = Engine.InstantiatePrefab(\n            prefabID,\n            initialPosition,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidLocalID(rootID) then\n            if Engine.IsValidLocalID(rootID) then\n                Engine.DeletePrefabInstance(rootID)\n            end\n            group:Delete()\n            Engine.Error(\"Unable to instantiate an EDA UEF factory construction beam for \" .. boneName .. \".\")\n            return nil\n        end\n\n        local beamEntityID = EngineClasses.LocalID()\n        Engine.GetLocalBone(rootID, \"Construction Beam\", beamEntityID)\n        if not Engine.IsValidLocalID(beamEntityID) then\n            Engine.DeletePrefabInstance(rootID)\n            group:Delete()\n            Engine.Error(\"The EDA UEF factory construction-beam prefab has no renderer entity.\")\n            return nil\n        end\n\n        table.insert(group.beams, {\n            rootID = rootID,\n            muzzleID = muzzleID,\n            muzzlePosition = EngineClasses.float3(),\n            beam = CreateConstructionBeam(rootID),\n        })\n    end\n\n    return group\nend\n\nlocal function DisposeEdaUefFactoryConstructionBeam(factory)\n    local beam = factory.constructionBeam\n    factory.constructionBeam = nil\n    factory.constructionBeamEnabled = false\n    if beam and beam.Delete then\n        beam:Delete()\n    end\nend\n\nlocal EDALandFactory = ClientEDALandFactory or EDALandFactory\nif not EDALandFactory then\n    error(\"SCO could not resolve the client EDA land-factory base class.\")\nend\nClientEDAUefLandFactory = Class(\"EDAUefLandFactory\", EDALandFactory)\nlocal EDAUefLandFactory = ClientEDAUefLandFactory\n\nfunction EDAUefLandFactory:CreateRollOffReservation()\n    if self.edaUefRollOffReservationIDs or self:IsPlacementGhost() then\n        return\n    end\n\n    local reservations = GetEdaUefFactoryRollOffReservations(self)\n    if #reservations == 0 then\n        return\n    end\n\n    local prefabID = GetEdaUefFactoryRollOffReservationPrefabID()\n    if not prefabID then\n        return\n    end\n\n    local reservationIDs = {}\n    local factoryPosition = self:GetPosition()\n    for _, reservation in ipairs(reservations) do\n        local size = reservation.size\n        if not size then\n            DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"EDA UEF factory local roll-off reservation is missing a size.\")\n            return\n        end\n\n        local offset = reservation.offset or {}\n        local position = EngineClasses.float3(\n            factoryPosition.x + (offset.x or 0),\n            factoryPosition.y + (offset.y or 0),\n            factoryPosition.z + (offset.z or 0)\n        )\n        local errorCode, reservationID = Engine.InstantiatePrefab(\n            prefabID,\n            position,\n            EngineClasses.float3(1, 1, 1),\n            GetIdentityQuaternion()\n        )\n        if errorCode ~= EngineErrorCode.Success or not Engine.IsValidLocalID(reservationID) then\n            if Engine.IsValidLocalID(reservationID) then\n                Engine.DeletePrefabInstance(reservationID)\n            end\n            DestroyEdaUefFactoryRollOffReservationIDs(reservationIDs)\n            Engine.Error(\"Unable to create an EDA UEF factory local roll-off reservation.\")\n            return\n        end\n\n        Engine.SetLocalGridModifierSize(reservationID, EngineClasses.float2(size.x, size.y))\n        table.insert(reservationIDs, reservationID)\n    end\n\n    self.edaUefRollOffReservationIDs = reservationIDs\n    self:SetRollOffReservationEnabled(self:IsIntelVisionVisible())\nend\n\nfunction EDAUefLandFactory:SetRollOffReservationEnabled(enabled)\n    for _, reservationID in ipairs(self.edaUefRollOffReservationIDs or {}) do\n        if Engine.IsValidLocalID(reservationID) then\n            Engine.SetLocalGridModifierEnabled(reservationID, enabled)\n        end\n    end\nend\n\nfunction EDAUefLandFactory:DestroyRollOffReservation()\n    DestroyEdaUefFactoryRollOffReservationIDs(self.edaUefRollOffReservationIDs)\n    self.edaUefRollOffReservationIDs = nil\nend\n\nfunction EDAUefLandFactory:__init(globalId, localId, armyId, template, progress)\n    EDALandFactory.__init(self, globalId, localId, armyId, template, progress)\n    if not self:IsPlacementGhost() then\n        self:CreateRollOffReservation()\n    end\nend\n\nfunction EDAUefLandFactory:OnPromoteToUnit()\n    self:CreateRollOffReservation()\n    EDALandFactory.OnPromoteToUnit(self)\nend\n\nfunction EDAUefLandFactory:OnIntelHidden()\n    EDALandFactory.OnIntelHidden(self)\n    self:SetRollOffReservationEnabled(false)\nend\n\nfunction EDAUefLandFactory:OnIntelVision()\n    EDALandFactory.OnIntelVision(self)\n    self:CreateRollOffReservation()\n    self:SetRollOffReservationEnabled(true)\nend\n\nfunction EDAUefLandFactory:SetUpConstructionBeam()\n    DisposeEdaUefFactoryConstructionBeam(self)\n    local boneNames = self.tp.additions and self.tp.additions.buildBeamBones\n    if boneNames and #boneNames > 0 then\n        self.constructionBeam = CreateEdaUefFactoryConstructionBeamGroup(self, boneNames)\n    end\nend\n\nfunction EDAUefLandFactory:OnStartBuildRoutine(buildableId)\n    self:SetUpConstructionBeam()\n    EDALandFactory.OnStartBuildRoutine(self, buildableId)\nend\n\nfunction EDAUefLandFactory:ClientOnStopBuilding()\n    EDALandFactory.ClientOnStopBuilding(self)\n    DisposeEdaUefFactoryConstructionBeam(self)\nend\n\nfunction EDAUefLandFactory:OnEndUpgrading(upgrade)\n    EDALandFactory.OnEndUpgrading(self, upgrade)\n    DisposeEdaUefFactoryConstructionBeam(self)\nend\n\nfunction EDAUefLandFactory:RenderUpdateBeams()\n    EDALandFactory.RenderUpdateBeams(self)\n    if self.constructionBeam then\n        self.constructionBeam:RenderUpdate()\n    end\nend\n\nfunction EDAUefLandFactory:OnIntelRadar()\n    EDALandFactory.OnIntelRadar(self)\n    self:RecalculateConstructionBeamState()\n    self:SetRollOffReservationEnabled(false)\nend\n\nfunction EDAUefLandFactory:OnDestroy(isDelete)\n    self:DestroyRollOffReservation()\n    DisposeEdaUefFactoryConstructionBeam(self)\n    EDALandFactory.OnDestroy(self, isDelete)\nend\n\nfunction EDAUefLandFactory:OnDelete()\n    self:DestroyRollOffReservation()\n    DisposeEdaUefFactoryConstructionBeam(self)\n    EDALandFactory.OnDelete(self)\nend"),
