eId, source.TargetId, "c23a48d6b47043144baafc4c7f47b5a470392264f1bbaf962896923d58899c26", source.SourceId, source.SourceId, source.BlueprintSha256, source.SourceId, source.SourceId, source.ScriptSha256, text3, text4, source.SourceId, source.SourceId, text2, source.Health, source.Health, source.BuildTime, source.Alloys, source.Energy, source.AlloyStorage, source.Vision, source.BuildPower, source.Faction, source.Tier, text);
