		string insertion = string.Join("\n", "", "-- Supreme Commander Overhaul Structures Cache Patcher 1.6.1", "-- Factory lanes are separate Default-grid roots. Resolve them to their owner", "-- so either faction treats its own lane as the target during placement validation.", "_G.SupremeCommanderOverhaulFactoryReservationOwners = _G.SupremeCommanderOverhaulFactoryReservationOwners or {}", "", "local function OverhaulFactoryReservationKey(id)", "    return tostring(id.index) .. \":\" .. tostring(id.version)", "end", "", "local function OverhaulFactoryReservationOwner(id)", "    return _G.SupremeCommanderOverhaulFactoryReservationOwners[OverhaulFactoryReservationKey(id)]", "end", "", "local function OverhaulFactoryPlacementReservationsAreClear(position, tp, armyId, targetUnit)", "    local reservations = tp.additions and tp.additions.placementReservations", "    if not reservations then", "        return true", "    end", "", "    for _, reservation in ipairs(reservations) do", "        local size = reservation.size", "        local offset = reservation.offset or {}", "        if not size then", "            return false", "        end", "        local center = EngineClasses.float3(", "            position.x + (offset.x or 0),", "            (position.y or 0) + (offset.y or 0),", "            position.z + (offset.z or 0)", "        )", "        local minX, minY, maxX, maxY = PlacementUtils.GetPlacementBounds(center, size)", "        local min = EngineClasses.int2(minX, minY)", "        local max = EngineClasses.int2(maxX, maxY)", "        local _, cells = Engine.GetGlobalGridCellFlags(_G.globalBuildingPlacementGridID, min, max)", "        for _, cell in ipairs(cells or {}) do", "            local flags = cell.flags", "            if not PlacementUtils.IsCellValidForPlacement(flags, PlacementUtils.GetPlacementDomain(tp), false) then", "                return false", "            end", "        end", "", "        local _, ids = Engine.GetGlobalGridModifiers(_G.globalBuildingPlacementGridID, min, max, PlacementLayer.Default)", "        for _, id in ipairs(ids or {}) do", "            local occupyingID = OverhaulFactoryReservationOwner(id) or id", "            local unit = GetUnitById(occupyingID)", "            local targetID = targetUnit and targetUnit.id", "            local isTarget = targetID and occupyingID.index == targetID.index and occupyingID.version == targetID.version", "            if not isTarget and unit and unit:IsIntelVisionVisible(Armies[armyId]) then", "                return false", "            end", "        end", "    end", "", "    return true", "end") + "\n";
		source = InsertAfterOnce(source, anchor, insertion, "the host build-order imports");
